import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BiXHgXAn.js";const u=JSON.parse('{"title":"","description":"Experiment to modify the behavior of the --force flag in Task","frontmatter":{"title":"Gentle Force (#1200)","description":"Experiment to modify the behavior of the --force flag in Task","section":"Project","docType":"project","outline":"deep"},"headers":[],"relativePath":"docs/experiments/gentle-force.md","filePath":"next/docs/experiments/gentle-force.md"}'),r={name:"docs/experiments/gentle-force.md"};function s(c,e,i,l,d,f){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="" tabindex="-1">Gentle Force (<a href="https://github.com/nirantarasi/nirantarasi.github.io/issues/1200" target="_blank" class="github-pr-link">#1200</a>) <a class="header-anchor" href="#" aria-label="Permalink to &quot;Gentle Force (#1200)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>All experimental features are subject to breaking changes and/or removal <em>at any time</em>. We strongly recommend that you do not use these features in a production environment. They are intended for testing and feedback only.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>This experiment breaks the following functionality:</p><ul><li>The <code>--force</code> flag</li></ul></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>To enable this experiment, set the environment variable: <code>TASK_X_GENTLE_FORCE=1</code>. Check out <a href="./#enabling-experiments">our guide to enabling experiments</a> for more information.</p></div><p>The <code>--force</code> flag currently forces <em>all</em> tasks to run regardless of the status checks. This can be useful, but we have found that most of the time users only expect the direct task they are calling to be forced and <em>not</em> all of its dependent tasks.</p><p>This experiment changes the <code>--force</code> flag to only force the directly called task. All dependent tasks will have their statuses checked as normal and will only run if Task considers them to be out of date. A new <code>--force-all</code> flag will also be added to maintain the current behavior for users that need this functionality.</p><p>If you want to migrate, but continue to force all dependent tasks to run, you should replace all uses of the <code>--force</code> flag with <code>--force-all</code>. Alternatively, if you want to adopt the new behavior, you can continue to use the <code>--force</code> flag as you do now!</p>',7)])])}const p=t(r,[["render",s]]);export{u as __pageData,p as default};
